class UpgradeTest(CSV4AllTest, ABC):

    def __init__(self, nodes_details: List[dict], test_nodes_details: List[dict], iterations_per_node: int,
                 report: bool, calculate_kpi: Optional[bool] = True, kpi_targets: Optional[dict] = None,
                 use_dcap: Optional[bool] = False, qc_domain: Optional[str] = None, qc_id: Optional[str] = None,
                 qc_project: Optional[str] = None, customers_list: Optional[list] = None,
                 report_comment: Optional[str] = None, sw_build: Optional[str] = None, topology: Optional[str] = None,
                 use_external_storage: Optional[bool] = False, download_path: Optional[str] = None,
                 use_testpackage: Optional[bool] = False, stop_test_after_fail: bool = False,
                 artifactory_location: Optional[str] = "espoo2", package_suffix: Optional[str] = "A54",
                 l3_call_method: Optional[callable] = None,
                 synchronize_software_on_passive: Optional[bool] = False, yaft_path: Optional[str] = "/home/ute",
                 virtualenv_dir: str = None, detailed_console_log: bool = True, ru_update_sw: bool = False,
                 collect_passed_logs: int = 0, swconfig_modification: bool = True, hwf_migration_check: bool = True,
                 kpi_to_calculate: list = None, diagnostic_check: bool = False):
        super().__init__(nodes_details, test_nodes_details, iterations_per_node, report, calculate_kpi, kpi_targets,
                         use_dcap, qc_domain, qc_id, qc_project, customers_list, report_comment,
                         sw_build, topology, stop_test_after_fail, l3_call_method, detailed_console_log,
                         collect_passed_logs)
        self.allowed_temporary_alarms_for_CB013223 = ["4367", "4352", "4670"]
        self.yaft_path = f"{yaft_path}/YAFT"
        self.l3_call_result = None
        self.source_firmware_version = None
        self.synchronize_software_on_passive = synchronize_software_on_passive
        self.use_testpackage = use_testpackage
        self.download_path = download_path
        self.use_ext_storage = use_external_storage
        self.reset_incrementation = True
        self.calculate_kpi = calculate_kpi
        self.uuf_case_type = "upgrade"
        self.additional_kpi = kpi_to_calculate
        self.kpi_to_calculate = KPI_PER_TEST_CASE.get("Upgrade")
        self.mplane_access_timeout = 300
        self.virtualenv_dir = virtualenv_dir
        self.wft = CSV4ALLWft(artifactory_location, package_suffix)
        self.uboot = CSV4ALLUboot()
        self.package_suffix = package_suffix
        self.ru_update_sw = ru_update_sw
        self.swconfig_modification = swconfig_modification
        self.hwf_migration_check = hwf_migration_check
        self.precheck_failed = False
        self.diagnostic_check = diagnostic_check

    def test_setup(self):
        super().test_setup()
        self._log_if_reports_to_uuf_wont_be_sent()
        self.check_source_and_target_sw()
        self.prepare_uboot_scripts()
        self.yaft_checkout()
        self.download_builds_from_wft({node.target_sw for node in self.test_nodes if node.target_sw})
        self.set_sw_path_for_nodes()
        self.check_validation_scf_before_test()
        if self.hwf_migration_check:
            self.hwf_migration_precheck()
        self.check_oran_files_exists()

    def run_test_precondition(self):
        with RobotWrapper("Test Precondition", "kw"):
            self.start_test_log_tracing()
            self.setup_admin_connections()
            failed_nodes = self.run_precheck_method()
            if failed_nodes:
                self.gather_mumin_logs_and_snapshot("test_precondition")
                if self.report_to_rp:
                    for node in self.test_nodes:
                        self.test_reporter.report_result_to_uuf_dashboard(node, "failed", "", self.current_iteration)
                self.run_recovery_method(failed_nodes)
                raise TestPreconditionFailed()
            if self.current_iteration_number > 1:
                self.check_for_additional_snapshot()
            self.stop_test_log_tracing(f"{self.current_logs_dir}/test_precondition")

    def test(self):
        try:
            self.run_iteration_precondition()
            self.failed_nodes = self.test_operation(None)
            self.report_results_to_uuf_dashboard()
        except Exception as e:
            self.stop_test_log_tracing(self.current_logs_dir)
            self.gather_mumin_logs_and_snapshot()
            test_logger("Iteration Failed!", "error")
            test_logger(e, "error")
            test_logger(traceback.format_exc(), log_level="debug", console=False)

            raise

        self.verify_failed_nodes_after_iteration()

        if self.l3_call_method and not self.l3_call_result:
            raise IterationFailedError("Iteration Failed. L3 Call failed.")

    def run_iteration_precondition(self):
        with RobotWrapper("Iteration Precondition", "kw"):
            self.start_test_log_tracing()
            for node in self.test_nodes:
                self._precondition(node)
                self.execute_l3_call(node)
            self.stop_test_log_tracing(f"{self.current_logs_dir}/iteration_precondition")

    @wrapper_decorator
    def _precondition(self, node):
        self._set_current_logs_dir(node)
        self.check_active_sw(node, node.source_sw)
        self.firmware_downgrade(node)
        self.dnr_partition_check(node)
        if self.swconfig_modification:
            self.remove_hwf_flag(node)

    def test_operation(self, node):
        self.set_timestamp_reporting_and_kpi()
        self.software_update_test()
        return self.failed_nodes

    def software_update_test(self, operation: str = "update"):
        with RobotWrapper("Software Update Test", "kw"):
            for node in self.test_nodes:
                self.update_sw(node, operation)

    @wrapper_decorator
    def update_sw(self, node, operation: str = "update"):
        self._update_sw(node, operation)
        self.summary_operation(node, "update", self.failed_nodes_during_update)

    def _update_sw(self, test_node, operation: str = "update"):
        self._set_current_logs_dir(test_node)
        if self.check_nodes_state_before_operation(test_node):
            self.failed_nodes[test_node.node_alias].update(self.update_sw_operation(test_node, operation))
        else:
            self.failed_nodes[test_node.node_alias].update({test_node.node_alias})
            self.failed_nodes_during_update = {test_node.node_alias}
        if self.l3_call_method:
            self.l3_call_result = self.execute_l3_call_scenario(test_node)

    @method_decorator()
    def update_sw_operation(self, node, operation: str = "update"):
        self.set_calculate_provision_download_kpi(node)
        self.set_target_sw_path(node)
        self.select_proper_sw_to_activate(node)
        try:
            self.multi_runner.start_log_tracing_all_nodes()
            self.multi_runner.start_watching_alarms_on_all_nodes()
            self.failed_nodes_during_update = self.perform_software_precheck(node)
            self.failed_nodes_during_update.update(self._perform_diagnostic_check(node))
            self.live_update_precheck(node)
            self.gather_blackbox_and_set_reset_counter(operation)
            self.add_all_allowed_specific_faults(node)
            self.independent_sw_update(node)
            node.update_sw_and_wait_for_reload(timeout=self.mplane_access_timeout)
            self.get_latest_ims_file(node, operation)
            self.configure_wts_if_needed(node)
            self.failed_nodes_during_update.update(self.verify_nodes_after_sw_change_operation(node, operation))
            return self.failed_nodes_during_update
        except Exception as e:
            test_logger(e, console=False)
            self.failed_nodes_during_update = {node.node_alias}
            node.btsverify.bts_fault_message += f"\n{str(e)}"
            if "Connection lost during progress ongoing" in str(e) or "not completed within timeout" in str(e):
                self.restart_admin_connection(node)
            if "not completed within timeout" in str(e):
                node.wait_till_sw_download_finish()
            self.failed_nodes_during_update.update(self.multi_runner.verify_all_nodes(10, 0))
            return self.failed_nodes_during_update
        finally:
            self.remove_allowed_alarms_from_nodes(self.nodes, self.all_allowed_specific_faults)
            if self.calculate_kpi:
                node.collect_infomodel_log_after_update(logs_dir=self.current_logs_dir)

    def stop_test_log_tracing(self, logs_dir):
        self.multi_runner.stop_log_tracing_and_download_from_all_nodes(logs_dir=logs_dir)

    @method_decorator()
    def set_sw_path_for_nodes(self):
        for node in self.test_nodes:
            node.target_sw_path = self.wft.target_sw_dict.get(f"{node.target_sw}_release_BTSSM_downloadable_"
                                                              f"{self.package_suffix}")
            if self.use_testpackage:
                target_sw_paths = {sw_path for sw_build, sw_path in self.wft.target_sw_dict.items()
                                   if sw_build.startswith(node.target_sw)}
                target_sw_paths_list = list(islice(cycle(target_sw_paths), self.iterations_per_node + 1))
                node.iter_target_sw_list = iter(target_sw_paths_list)
                new_line = '\n'
                test_logger(f"{node.node_alias} will use:\n{new_line.join([path for path in target_sw_paths])}")
            else:
                test_logger(f"{node.node_alias} will use: {node.target_sw_path}")
            if node.oran_files:
                if node.oran_files.get("upgrade"):
                    test_logger(f"{node.node_alias} will use OFEGSA Update SW: {node.oran_files['upgrade']}")
                if node.oran_files.get("rollback"):
                    test_logger(f"{node.node_alias} will use OFEGSA Rollback SW: {node.oran_files['rollback']}")

    def run_test_verification(self, node, hw_timer: int = None, alarm_timer: int = None):
        return self.failed_nodes_during_update

    def verify_nodes_after_sw_change_operation(self, node, operation):
        if node.ru_manager:
            node.execute_commands_on_rmods()
        failed_nodes_during_operation = self.multi_runner.verify_all_nodes()
        failed_nodes_during_operation.update(self.multi_runner.stop_logs_and_verify_on_all_nodes(
            f"{self.current_logs_dir}/{operation}", node, self.reset_incrementation))
        if operation == "update":
            failed_nodes_during_operation.update(self.dnr_partition_check(node, True))
            if self.current_iteration == "Iteration_1":
                failed_nodes_during_operation.update(self.validate_scf(node, test_phase="after_update"))
            if self.hwf_migration_check and node.hwf_migration_check:
                failed_nodes_during_operation.update(self.check_hwf_migration_status(node))
        failed_nodes_during_operation.update(self.check_rmod_blackbox(node, operation))
        return failed_nodes_during_operation

    @method_decorator()
    def perform_uboot_downgrade_if_needed(self, node):
        uboot_result = self.perform_uboot_downgrade(node)
        if not uboot_result:
            node.btsverify.bts_fault_message += "\nFirmware downgrade failed"
            test_logger(f"[{node.node_alias}] UBOOT FAILED", "ERROR")
            self.gather_mumin_logs_and_snapshot("uboot")
            failed_nodes = self.precheck_method()
            if failed_nodes:
                self.recovery_after_uboot(failed_nodes)

    @method_decorator()
    def perform_uboot_downgrade(self, node):
        if not node.uboot_downgrade():
            return False
        if node.uboot.perform_reset:
            try:
                test_logger(f"[{node.node_alias}] Resetting site after uboot downgrade")
                node.reset_site()
                node.verify_node_bts_state()
                node.start_watching_alarms()
                node.verify_node_state()
                if not node.recheck_uboot_results():
                    return False
                test_logger(f"[{node.node_alias}] UBOOT PASSED", hyperlink=True)
            except Exception as e:
                test_logger(e, "error")
                return False
        return True

    @method_decorator()
    def run_kpi_calculation(self, node):
        try:
            test_logger("Calculating OAM KPI")
            self.select_upgrade_kpi(node)
            self.kpi.kpi_calc.serial_console_connected = len(node.btsverify.cells_verifier.serial_console_cells) > 0
            self.kpi.set_end_timestamp_for_kpi_calculation()
            self.kpi.calculate_proper_oam_kpi(f"{self.current_logs_dir}/oam_kpis/update/")
            self.kpi.kpi_results_from_current_iteration = self.kpi.get_kpi_results()
        except Exception as e:
            test_logger(e, console=False)
            test_logger("KPI Calculation failed", "error")
        finally:
            if self.report_to_rp:
                result = "failed" if self.failed_nodes[node.node_alias] or self.precheck_failed else "passed"
                self.test_reporter.report_result_to_uuf_dashboard(node, result,
                                                                  self.kpi.get_uuf_kpi(self.uuf_case_type),
                                                                  self.current_iteration,
                                                                  self.kpi.get_kpi_results())

                self.kpi.clear_kpi_results()

    @method_decorator()
    def select_upgrade_kpi(self, node):
        firmware_update_performed = node.check_if_firmware_changed_after_upgrade()
        if node.source_sw.split("_")[0] != node.target_sw.split("_")[0]:
            if not firmware_update_performed:
                self.kpi_to_calculate = ["kpi2a", "kpi2k"]
            else:
                self.kpi_to_calculate = ["kpi2b", "kpi2k"]
        else:
            if not firmware_update_performed:
                self.kpi_to_calculate = ["kpi2c"]
            else:
                self.kpi_to_calculate = ["kpi2d"]
        if self.additional_kpi:
            if isinstance(self.additional_kpi, str):
                self.additional_kpi = [self.additional_kpi]
            self.kpi_to_calculate += self.additional_kpi
            self.kpi_to_calculate = list(set(self.kpi_to_calculate))
            self.kpi_to_calculate = [kpi for kpi in self.kpi_to_calculate if kpi]
        self.kpi.kpi_names = self.kpi_to_calculate
        if node.calculate_provision_download_kpi:
            self.kpi.kpi_names += ["kpi4a", "kpi4b", "KPISwDownload", "KPISwProvision"]
        test_logger(f"Selected KPI for upgrade calculation : {self.kpi_to_calculate}", "info")

    def exception_handling(self, operation: str, exception):
        test_logger(exception, console=False)
        try:
            self.gather_mumin_logs_and_snapshot(operation)
        except Exception as e:
            test_logger(e, console=False)

    @method_decorator()
    def download_builds_from_wft(self, list_of_builds, download_candidate: bool = True):
        def download_builds():
            try:
                self.wft.download_build_from_wft(
                    builds_to_download=list_of_builds,
                    use_build_storage=self.use_ext_storage,
                    download_path=self.download_path,
                    test_package=self.use_testpackage,
                    download_candidate=download_candidate)
            except Exception as e:
                self.wft.set_download_failed()
                if "No space left on device" in str(e):
                    raise FatalError("No space left on device to download build from WFT!")
                raise e

        test_logger("Download builds from WFT")
        verify_function_x_times(3, 30, download_builds)

    @staticmethod
    def _check_if_sw_are_similar(node):
        return "_".join(node.target_sw.split("_")[:-1]) == "_".join(node.source_sw.split("_")[:-1])

    @method_decorator()
    def prepare_uboot_scripts(self):
        self.uboot.prepare_uboot_scripts()

    def set_timestamp_reporting_and_kpi(self):
        if self.calculate_kpi:
            self.kpi.set_start_timestamp_for_kpi_calculation()
        if self.report_to_rp:
            self.test_reporter.get_start_time()

    def report_results_to_uuf_dashboard(self):
        with RobotWrapper("Report Results to UUF Dashboard", "kw"):
            if self.report_to_rp:
                self.test_reporter.get_end_time()
            for node in self.test_nodes:
                self._set_current_logs_dir(node)
                if self.calculate_kpi:
                    self.run_kpi_calculation(node)
                elif node.live_update and self.report_to_rp:
                    result = "failed" if self.failed_nodes[node.node_alias] or self.precheck_failed else "passed"
                    self.test_reporter.report_result_to_uuf_dashboard(node, result, "", self.current_iteration)

    @method_decorator()
    def check_nodes_state_before_operation(self, node, operation: str = "update"):
        failed_nodes = self.precheck_method()
        if failed_nodes:
            self.gather_mumin_logs_and_snapshot(f"before_{operation}")
            try:
                self.run_recovery_method(failed_nodes)
            except RecoveryAttemptFailedError:
                self.failed_nodes[node.node_alias].update({node.node_alias})
                self.report_results_to_uuf_dashboard()
                raise
            return False
        return True

    @method_decorator()
    def dnr_partition_check(self, node, after_upgrade: bool = False):
        test_logger("DNR partition check")
        not_supported_smods = ["FSMF", "FSIH", "ASOG", "ASOH"]
        failed_nodes = set()
        if self.yaft_configured:
            test_phase = "after upgrade" if after_upgrade else "before upgrade"
            smod = node.ssh_manager.get_module_type()
            if smod not in not_supported_smods:
                node.set_fdsw_builds(test_phase)
                failed_nodes.update(self.perform_dnr_partition_check(node, after_upgrade))
            if node.secondary_vm and node.ssh_manager.is_slave_smod() \
                    and node.ssh_manager.get_module_type(True) not in not_supported_smods:
                node.set_fdsw_builds(test_phase, True)
                failed_nodes.update(self.perform_dnr_partition_check(node, after_upgrade, True))
        return failed_nodes

    @method_decorator()
    def perform_dnr_partition_check(self, node, check_after_upgrade: bool = False, slave_smod: bool = False):
        try:
            smod = list(node.systemModules.keys())[0 if not slave_smod else 1]
            smod = f"{node.systemModules[smod].get('Module Type')}-{smod.split('-')[-1]}"
            node_alias = f"{node.node_alias} secondary core" if slave_smod else node.node_alias
            test_phase = "after upgrade" if check_after_upgrade else "before upgrade"
            node.set_fdsw_builds(test_phase, slave_smod)
            if node.fdsw_builds[smod][test_phase]["fs3"] != node.fdsw_builds[smod][test_phase]["active"]:
                if check_after_upgrade:
                    raise DnrAlignmentError(f"Build on dnr partition on {smod} {test_phase} is different")
                test_logger(f"DnR partition alignment started on {node_alias}")
                build = node.fdsw_builds[smod][test_phase]["active"]
                self.download_builds_from_wft(build)
                self.run_yaft_to_align_dnr_partition(node, smod, build, slave_smod)
            else:
                test_logger(f"DnR is aligned with active partition on {node_alias}")
            return set()
        except Exception as e:
            test_logger(e, "ERROR")
            if self.notifications:
                self.notifications.send_email(body=f"{str(e)}\n{json.dumps(node.fdsw_builds, indent=4)}",
                                              subject=f"FDSW DNR CHECK FAILED FOR {node.testline_scout_name}",
                                              text_type="plain")

            node.btsverify.bts_fault_message += f"\nFDSW DnR check failed on {node.node_alias}"
            return {node.node_alias}
        finally:
            node.stop_dnr_ffs3_mount(slave_smod)

    @method_decorator()
    def yaft_checkout(self) -> None:
        def modify_yaft_file():
            """
            Function removing --clean_to_default flag from yaft command when --flash_failsafe_partition flag is used.
            CNNed PRs: PR800176/PR800686
            """
            with open(f"{self.yaft_path}/yaft.py", "r") as yaft_file:
                yaft_data_lines = yaft_file.readlines()

            with open(f"{self.yaft_path}/yaft.py", "w") as yaft_modified:
                skip_next_line = False
                for line in yaft_data_lines:
                    if 'print("  --clean_to_default")' in line:
                        skip_next_line = True
                    elif skip_next_line:
                        skip_next_line = False
                    else:
                        yaft_modified.write(line)

        commands = [f"rm -rf {self.yaft_path}",
                    f"svn checkout https://svne1.access.nsn.com/isource/svnroot/BTS_T_YAFT/trunk {self.yaft_path} "
                    f"--username ca_uuf --password ca_uuf_pass"]
        try:
            for command in commands:
                test_logger(f"Executing command: {command}", console=False)
                output = wait_until_success(120, 10, run_process, command)
                test_logger(output, console=False)
            modify_yaft_file()
            self.yaft_configured = True
        except Exception as e:
            test_logger(e, "ERROR")
            self.yaft_configured = False

    @method_decorator()
    def run_yaft_to_align_dnr_partition(self, node, smod, build, slave: bool = False):
        def perform_recheck_after_yaft():
            test_phase = "after fs3 partition yaft"
            node.set_fdsw_builds(test_phase, slave)
            if node.fdsw_builds[smod][test_phase]["fs3"] != node.fdsw_builds[smod][test_phase]["active"]:
                raise DnrAlignmentError(f"Build on dnr partition {test_phase} is different on {node_alias}")
            else:
                test_logger(f"DnR partition alignment finished successfully on {node_alias}")

        node_alias = f"{node.node_alias} secondary core" if slave else node.node_alias
        download_path = self.wft.target_sw_dict.get(f"{build}_release_BTSSM_downloadable")
        commands = [f"cp -R {download_path} {self.yaft_path}",
                    f"cp {node.backup_swconfig_path_primary_smod} "
                    f"{self.yaft_path}/libyaft/swconfig.txt"]

        tunnel_port = "2222"
        yaft_command = f'echo "{node.node_ssh_password}" | ' \
                       f'python {self.yaft_path}/yaft.py -i localhost -P {tunnel_port} -z ' \
                       f'{self.yaft_path}/{build}*.zip --ask_for_password -K ' \
                       f'--flash_failsafe_partition'
        commands.append(yaft_command)
        ssh_tunnel_process = None
        try:
            ssh_tunnel_process = self.start_ssh_tunnel(node, tunnel_port, slave)
            for command in commands:
                test_logger(f"Executing command: {command}", console=False)
                output = wait_until_success(120, 10, run_process, command)
                test_logger(output, console=False)
            perform_recheck_after_yaft()
        except Exception as e:
            test_logger(e, "ERROR")
            raise e
        finally:
            self.stop_ssh_tunnel(ssh_tunnel_process)

    @staticmethod
    @method_decorator("node_alias")
    def mount_and_get_dnr_partition(node, is_slave: bool = False):
        try:
            if node.ssh_manager.execute_command("df -h | grep dnr", slave_smod=is_slave):
                dnr_dir = "/ffs/dnr"
            elif node.ssh_manager.execute_command("df -h | grep fs3 | awk '{print $6}'", slave_smod=is_slave):
                dnr_dir = "/ffs/fs3"
            else:
                node.ssh_manager.execute_command("systemctl start ffs-fs3.mount", slave_smod=is_slave)
                dnr_dir = "/ffs/fs3"

            test_logger(f"DnR mount directory: {dnr_dir}", "DEBUG")
            return dnr_dir
        except Exception as e:
            test_logger(e, "error")
            return False

    @method_decorator()
    def validate_scf(self, test_node, logs_dir: str = None, test_phase: str = None):
        try:
            test_node.validate_current_scf(log_dir=logs_dir if logs_dir else f"{self.current_logs_dir}/update/"
                                                                             f"SCF_VALIDATION_{test_node.node_alias}",
                                           test_phase=test_phase)
            return set()
        except Exception as e:
            test_logger(e, "DEBUG")
            test_logger("Validation scf failed!", "error")
            test_node.btsverify.bts_fault_message += f"\nValidation scf failed on {test_node.node_alias}"
            return {test_node.node_alias}

    @staticmethod
    def get_timestamp():
        return str(datetime.now().strftime('%Y%m%d-%H%M'))

    def summary_operation(self, node, operation, failed_nodes):
        if failed_nodes:
            test_logger(f"Nodes failed during {operation.upper()}: {','.join(failed_nodes)}", "error")
            test_logger(f"[{node.node_alias}] {operation.upper()} SW FAILED", "error")
            self.gather_mumin_logs_and_snapshot(operation)
            if self.stop_test_after_fail:
                self.report_results_to_uuf_dashboard()
                raise FatalError(f"Test has been stopped, stop_test_after_fail is True")
        else:
            test_logger(f"[{node.node_alias}] {operation.upper()} SW PASSED", hyperlink=True)
            if not self.passed_logs_gathered:
                self.gather_mumin_logs_and_snapshot(operation)

    @method_decorator()
    def check_validation_scf_before_test(self):
        failed_nodes = set()
        for node in self.test_nodes:
            failed_nodes.update(self.validate_scf(node, f"{self.log_dir}/TEST_SETUP_{node.node_alias}",
                                                  test_phase="before_update"))
        if failed_nodes:
            raise FatalError(f"Validation initial scf failed on {', '.join(failed_nodes)}!")

    @method_decorator()
    def hwf_migration_precheck(self):
        for node in self.test_nodes:
            hwf_info = node.get_hwf_infomodel_info()
            if hwf_info:
                test_logger(f"[{node.node_alias}] HWF Migration feature is available on {node.source_sw}, "
                            f"check will be done after upgrade")
                node.hwf_migration_check = True
            else:
                test_logger(f"[{node.node_alias}] HWF Migration feature is not available on {node.source_sw}, "
                            f"check will be skipped")
                node.hwf_migration_check = False

    @staticmethod
    @function_wrapper
    def start_ssh_tunnel(node, port: str, slave: bool = False):
        ssh_command = [
            "sshpass", "-p", node.vm.get('password'),
            "ssh", "-N", "-L", f"{port}:{node.bts_host_ip}:22",
            "-o", "StrictHostKeyChecking=no", "-o", "UserKnownHostsFile=/dev/null",
            f"{node.vm.get('user')}@{node.vm.get('host')}"
        ]
        if slave and node.secondary_vm:
            ssh_command_secondary = [
                "sshpass", "-p", node.secondary_vm.get('password'),
                "ssh", "-N", "-L", f"{port}:{node.secondary_vm.get('bts_host_ip')}:22",
                "-o", "StrictHostKeyChecking=no", "-o", "UserKnownHostsFile=/dev/null",
                f"{node.secondary_vm.get('user')}@{node.secondary_vm.get('host')}"
            ]
            process = subprocess.Popen(ssh_command_secondary, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        else:
            process = subprocess.Popen(ssh_command, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        time.sleep(2)
        return process

    @staticmethod
    @function_wrapper
    def stop_ssh_tunnel(process):
        if process:
            process.terminate()
            process.wait()

    @staticmethod
    def check_hwf_migration_status(test_node):
        try:
            test_node.check_hwf_migration()
            return set()
        except HWFMigrationError as hwf_error:
            test_node.btsverify.bts_fault_message += f"\n{str(hwf_error)}"
            return {test_node.node_alias}

