    def firmware_downgrade(self, node):
        if self.mumin:
            self.bmu_downgrade(node)
        if self.uboot.uboot_scripts_prepared:
            self.perform_uboot_downgrade_if_needed(node)

    @method_decorator()
    def bmu_downgrade_rmods_precheck(self, node) -> bool:
        try:
            if self.rmods_bmu_downgrade_check(node):
                node.verify_node_bts_state()
                node.start_watching_alarms()
                node.watchdog.allow_alarm(fault_id="4589")
                node.verify_node_state()
                node.watchdog.disallow_alarm(fault_id="4589")
                test_logger(f"[{node.node_alias}] BMU DOWNGRADE PASSED")
            return True
        except Exception as e:
            test_logger(e, "DEBUG")
            return False

    @method_decorator()
    def rmods_bmu_downgrade_check(self, node):
        rmod_downgraded = False
        for rmod_details in node.radioModules.values():
            smod_type = rmod_details["Module Type"]
            if smod_type in ["AEHC", "AEHB"]:
                serial_number = rmod_details["Serial Number"]
                if serial_number in self.mumin.rf_diagnostic_card.rmod_connections:
                    rmod_downgraded = True if self.bmu_downgrade_check(serial_number) else rmod_downgraded
                else:
                    test_logger(f"[{serial_number}] RMOD is not connected to MUMIN, BMU downgrade can't be done")

        return rmod_downgraded

    @method_decorator()
    def bmu_downgrade_check(self, rmod_serial: str) -> bool:
        try:
            test_logger(f"Checking BMU version on: {rmod_serial}")
            self.mumin.rf_diagnostic_card.send_command(cmd="touch /mnt/runtime/nodfelog", alias=rmod_serial)
            bmu_version = self.getting_bmu_version("i2cget -y -f 3 0x3c 0x0", rmod_serial)
            test_logger(f"BMU version before downgrade: {bmu_version}", "DEBUG")
            bmu_sw_version = self.getting_bmu_version("head -n1 /mnt/slot_running/bmu.metadata", rmod_serial)
            test_logger(f"BMU version sw installed: {bmu_sw_version}", "DEBUG")
            if bmu_version != bmu_sw_version:
                self.perform_bmu_downgrade(rmod_serial)
                return True
            test_logger("BMU Downgrade not needed, versions are the same")
            return False
        finally:
            self.mumin.rf_diagnostic_card.send_command(cmd="rm -rf /mnt/runtime/nodfelog", alias=rmod_serial)

    @method_decorator()
    def perform_bmu_downgrade(self, rmod_serial: str):
        test_logger(f"Performing BMU downgrade on: {rmod_serial}")
        bmu_sw_version_file_cmd = f"ls -r /lib/firmware/AEHB* | head -n 1 | awk -F'/' '{{print $NF}}'"
        bmu_sw_version_file = self.mumin.execute_command_on_rmod(command=bmu_sw_version_file_cmd,
                                                                 rmod_serial=rmod_serial).strip("'\x00\n").strip()
        bmu_downgrade_cmd = f"cd /lib/firmware; echo -n {bmu_sw_version_file} > " \
                            f"/sys/bus/i2c/drivers/machxo2/3-0040/update; sleep 3; "
        self.mumin.execute_command_on_rmod(command="sudo su;", rmod_serial=rmod_serial)
        bmu_downgrade = self.mumin.execute_command_on_rmod(command=bmu_downgrade_cmd,
                                                           rmod_serial=rmod_serial,
                                                           wait_time=300).strip("'\x00\n").strip()
        test_logger(f"BMU downgrade finished: {bmu_downgrade}", "DEBUG")
        test_logger(f"Performing reset BMU", "DEBUG")
        self.mumin.rf_diagnostic_card.send_command(cmd="i2cset -y -f 3 0x40 0x79 0x0000 w", alias=rmod_serial)
        time.sleep(10)
        test_logger(f"Recheck BMU version", "DEBUG")
        try:
            recheck_bmu_version = self.getting_bmu_version("i2cget -y -f 3 0x3c 0x0", rmod_serial, 300)
            test_logger(f"BMU version after downgrade: {recheck_bmu_version}", "DEBUG")
            bmu_sw_version = self.getting_bmu_version("head -n1 /mnt/slot_running/bmu.metadata", rmod_serial)
            if recheck_bmu_version != bmu_sw_version:
                test_logger(f"[{rmod_serial}] BMU version after downgrade is different!", "ERROR")
                raise
            test_logger(f"BMU version downgraded successfully on: {rmod_serial}")
        except Exception as e:
            test_logger(e, "DEBUG")
            raise BMUDowngradeError()

    @method_decorator()
    def get_bmu_version(self, command: str, rmod_serial: str, wait_on_rmod: int = 30) -> int:
        try:
            bmu_version = self.mumin.execute_command_on_rmod(command=command,
                                                             rmod_serial=rmod_serial,
                                                             wait_on_rmod=wait_on_rmod).strip("'\x00\n").strip()
            if '0x' in bmu_version:
                bmu_version = int(bmu_version, 16)
            return int(bmu_version)
        except Exception as e:
            test_logger(e, "DEBUG")
            if "BREAK" in str(e):
                self.mumin.reconnect_rmod(rmod_serial)
            raise e

    @method_decorator()
    def getting_bmu_version(self, command: str, rmod_serial: str, wait_on_rmod: int = 30):
        return wait_until_success(600, 30, self.get_bmu_version, command, rmod_serial, wait_on_rmod=wait_on_rmod)

    def recovery_after_uboot(self, failed_nodes: set):
        try:
            self.gather_mumin_logs_and_snapshot("precheck_uboot")
            self.run_recovery_method(failed_nodes)
            test_logger("BTS is OK to continue testing")
        except RecoveryAttemptFailedError as recovery_error:
            test_logger(recovery_error, "ERROR")
            raise UbootDowngradeError()

    def bmu_downgrade(self, node):
        if not self.bmu_downgrade_rmods_precheck(node):
            node.btsverify.bts_fault_message += "\nBMU downgrade failed"
            test_logger(f"[{node.node_alias}] BMU DOWNGRADE FAILED", "ERROR")
            self.gather_mumin_logs_and_snapshot("uboot")
            failed_nodes = self.precheck_method()
            if failed_nodes:
                self.recovery_after_uboot(failed_nodes)

