    @method_decorator()
    def add_all_allowed_specific_faults(self, node):
        def check_if_dual_asim():
            for test_node in self.test_nodes:
                if len(test_node.systemModules) == 2:
                    module_types = [smod_details["Module Type"] for smod_details in test_node.systemModules.values()]
                    if module_types.count("ASIM") == 2:
                        return True
            return False

        super().add_all_allowed_specific_faults(node)
        if node.target_sw.startswith("SBTS00") and check_if_dual_asim():
            for alarm in self.allowed_temporary_alarms_for_CB013223:
                node.add_temporary_alarm(alarm)

    def check_if_dual_asim(self):
        for node in self.test_nodes:
            if len(node.systemModules) == 2:
                module_types = [smod_details["Module Type"] for smod_details in node.systemModules.values()]
                if module_types.count("ASIM") == 2:
                    return True
        return False
